#include "common.h"

extern s8 D_80080B70s[] __asm__("D_80080B70");

s32 func_8004E9EC(u8 *q, s32 n) {
    s32 i;
    s32 r;
    s32 a;
    s32 b;
    s32 c;
    s32 m;
    s8 *p;
    s32 kk;

    /* DEVICE D1: copy of n with no register preference. Worth the first
     * word `addu $t2,$a1,$zero` and r in $a1; a legal `kk = n` inherits
     * n's $a1 preference and lands at 31 words. The dead output r pins
     * `r = 0` after n's death. No -Wall warning. */
    __asm__("" : "=r"(kk), "=r"(r) : "0"(n));
    r = 0;
    i = 0;
    while (i <= kk * 2) {
        if (q[i] == 0) {
            m = kk * 2;
            while (i < m) {
                p = D_80080B70s;
                /* DEVICE D2: opaque value for p. Stops cse folding p[0] to
                 * `lb %lo(D)($hi)` and stops loop.c hoisting the lo_sum.
                 * Without it: 31 DIFF, p in $v0, first load off $t1. */
                __asm__("" : "=r"(p) : "0"(p));
                a = p[0];
                b = p[1];
                c = p[2];
                /* DEVICE D3: dead set of p (second death, p goes to
                 * global-alloc and takes $a1) and a/b/c tied so the stores'
                 * sched priority drops to 1 and `i += 2` follows them.
                 * Without it: 31 DIFF. With m tied instead: 15 DIFF. */
                __asm__("" : "=r"(p), "=r"(a), "=r"(b), "=r"(c) : "1"(a), "2"(b), "3"(c));
                q[i] = a;
                q[i + 1] = b;
                q[i + 2] = c;
                i += 2;
            }
            r = 1;
        }
        i++;
    }
    return r;
}
